  "publicTaskContract": {
    "publicContract": {
      "goal": "Apply a requested BGP policy edit while preserving its prefix-set scope, maximum-prefix bound, and local-route preference invariant.",
      "inputGrammar": {
        "notation": "TypeScript",
        "definition": "type RouteView = { requestId:string, intent:'remove-target-from-backbone', targetSite:string, policy:{termActive:boolean,prefixListActive:boolean,prefixes:string[],localPreference:number}, localPreference:number, maximumPrefixes:number }",
        "validExamples": [
          "{\"requestId\":\"r1\",\"intent\":\"remove-target-from-backbone\",\"targetSite\":\"ATL\",\"policy\":{\"termActive\":true,\"prefixListActive\":true,\"prefixes\":[\"10.1.0.0/16\"],\"localPreference\":200},\"localPreference\":100,\"maximumPrefixes\":2}"
        ],
        "invalidExamples": [
          "{\"intent\":\"reroute-everything\",\"policy\":{\"prefixes\":\"all\"}}"
        ]
      },
      "outputGrammar": {
        "notation": "TypeScript",
        "definition": "type RoutePatch = { termActive:boolean, prefixListActive:boolean, prefixes:string[], policyLocalPreference:number, decision:'APPLY'|'REFUSE' }",
        "validExamples": [
          "{\"termActive\":false,\"prefixListActive\":true,\"prefixes\":[\"10.1.0.0/16\"],\"policyLocalPreference\":200,\"decision\":\"APPLY\"}"
        ],
        "invalidExamples": [
          "{\"prefixListActive\":false,\"decision\":\"APPLY\"}"
        ]
      },
      "stateSemantics": {
        "initialState": "POLICY_LOADED",
        "states": [
          "POLICY_LOADED",
          "PATCH_SIMULATED",
          "PATCH_APPLIED",
          "PATCH_REFUSED"
        ],
        "transitions": [
          {
            "id": "simulate-route-policy-patch",
            "from": "POLICY_LOADED",
            "input": "Submit one RoutePatch to routing.simulate before any apply call.",
            "to": "PATCH_SIMULATED",
            "effect": "The facade returns counts only for advertised prefixes and locality violations under the patch."
          },
          {
            "id": "apply-only-safe-route-patch",
            "from": "PATCH_SIMULATED",
            "input": "Call routing.apply only when advertisedPrefixes is at most maximumPrefixes and localityViolations is zero.",
            "to": "PATCH_APPLIED",
            "effect": "The host records the propagated routes and resulting traffic destinations."
          }
        ]
      },
      "acceptedOutcomes": [
        "The target policy term is disabled, its prefix condition remains intact, simulation is safe, and exactly that patch is applied."
      ],
      "forbiddenOutcomes": [
        "Disabling or deleting the prefix condition while leaving the accepting term active, exceeding maximumPrefixes, or outranking local server routes."
      ],
      "safetyObligations": [
        "Never apply a patch whose simulated advertisements exceed maximumPrefixes or whose policy preference attracts another site's local routes."
      ],
      "livenessObligations": [
        "Simulate every valid requested patch and apply it when both public safety tests pass."
      ],
      "implementationFreedom": [
        "Patch construction and internal policy representation may vary while the emitted RoutePatch uses the exact public fields."
      ],
      "nonrequirements": [
        "Real BGP sockets, vendor configuration syntax, convergence timing, packet forwarding, and traffic optimization are outside this task."
      ]
    },
    "grading": {
      "rules": [
        {
          "id": "route-prefix-condition-preserved",
